# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#0f172a" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#f8fafc">KÜTLE ÇEKİM POTANSİYEL ENERJİSİ: Eₚ = -G · (M · m) / d</text>\n\n  <!-- Gezegen M -->\n  <circle cx="115" cy="135" r="48" fill="#1d4ed8" stroke="#60a5fa" stroke-width="3"/>\n  <text x="115" y="132" text-anchor="middle" font-size="14" font-weight="bold" fill="#ffffff">Gezegen</text>\n  <text x="115" y="150" text-anchor="middle" font-size="13" font-weight="bold" fill="#93c5fd">(Kütle M)</text>\n  <circle cx="115" cy="135" r="3" fill="#ffffff"/>\n\n  <!-- Uydu m -->\n  <circle cx="345" cy="135" r="22" fill="#f59e0b" stroke="#fde047" stroke-width="2.5"/>\n  <text x="345" y="139" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">m</text>\n  <circle cx="345" cy="135" r="2.5" fill="#0f172a"/>\n\n  <!-- Uzaklık d çizgisi -->\n  <line x1="115" y1="205" x2="345" y2="205" stroke="#38bdf8" stroke-width="2"/>\n  <line x1="115" y1="135" x2="115" y2="212" stroke="#94a3b8" stroke-width="1.2" stroke-dasharray="4,3"/>\n  <line x1="345" y1="135" x2="345" y2="212" stroke="#94a3b8" stroke-width="1.2" stroke-dasharray="4,3"/>\n  <text x="230" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#38bdf8">Kütle merkezleri uzaklığı (d)</text>\n  <text x="230" y="232" text-anchor="middle" font-size="11.5" fill="#e2e8f0">d arttıkça (uzaklaştıkça) Eₚ ARTAR, d → ∞ iken Eₚ = 0 olur.</text>\n\n  <!-- Sağ Kutu: Örnek Karşılaştırma -->\n  <rect x="415" y="48" width="265" height="190" rx="10" fill="#1e293b" stroke="#475569" stroke-width="2"/>\n  <text x="547" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#fbbf24">ÖRNEK YÖRÜNGE KARŞILAŞTIRMASI</text>\n  <line x1="430" y1="82" x2="665" y2="82" stroke="#334155" stroke-width="1.5"/>\n  <text x="432" y="106" font-size="11" fill="#93c5fd">• X Uydusu: kütle = 9m, yarıçap = 3d</text>\n  <text x="442" y="124" font-size="11" font-weight="bold" fill="#f8fafc">Eₚ(X) = -G·M·(9m)/(3d) = -3·G·Mm/d</text>\n  <text x="432" y="152" font-size="11" fill="#6ee7b7">• Y Uydusu: kütle = 12m, yarıçap = 4d</text>\n  <text x="442" y="170" font-size="11" font-weight="bold" fill="#f8fafc">Eₚ(Y) = -G·M·(12m)/(4d) = -3·G·Mm/d</text>\n  <rect x="440" y="186" width="215" height="34" rx="6" fill="#065f46" stroke="#10b981"/>\n  <text x="547" y="208" text-anchor="middle" font-size="12" font-weight="bold" fill="#ecfdf5">Sonuç: Eₚ(X) = Eₚ(Y)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KURTULMA ENERJİSİ VE GÖK CİSİMLERİNDEN KURTULMA HIZLARI</text>\n\n  <!-- Sol Kutu: Formül ve Kütleden Bağımsızlık -->\n  <rect x="18" y="45" width="315" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="175" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">KURTULMA ENERJİSİ (YÜZEYDEN SONSUZA)</text>\n  <rect x="36" y="78" width="278" height="32" rx="6" fill="#dbeafe" stroke="#3b82f6"/>\n  <text x="175" y="99" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">E(kurtulma) = -Eₚ = +G · (M · m) / R</text>\n  <text x="32" y="130" font-size="11" fill="#1e293b">• Sonsuzda: v(∞) = 0 ve E(toplam) = 0 olur.</text>\n  <text x="32" y="150" font-size="11" fill="#1e293b">• Kurtulma hızı cismin kütlesine (m) BAĞLI DEĞİLDİR!</text>\n  <rect x="34" y="164" width="282" height="64" rx="6" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="175" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Elma vs. Uzay Aracı (Dünya Yüzeyinde):</text>\n  <text x="175" y="202" text-anchor="middle" font-size="10.5" fill="#7f1d1d">Kurtulma Hızları EŞİT (40.320 km/h ≈ 11,2 km/s)</text>\n  <text x="175" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">Kurtulma Enerjileri FARKLI (m farklı olduğu için)</text>\n\n  <!-- Sağ Kutu: Gök Cisimlerinden Kurtulma Hızları Tablosu -->\n  <rect x="350" y="45" width="332" height="198" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="516" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">GÜNEŞ SİSTEMİNDE KURTULMA HIZLARI</text>\n  <line x1="366" y1="76" x2="666" y2="76" stroke="#86efac" stroke-width="1.5"/>\n  <text x="370" y="98" font-size="11" font-weight="bold" fill="#14532d">• Ay (En düşük):</text>\n  <text x="545" y="98" font-size="11" font-weight="bold" fill="#166534">8.280 km/h</text>\n  <text x="370" y="122" font-size="11" font-weight="bold" fill="#14532d">• Mars:</text>\n  <text x="545" y="122" font-size="11" font-weight="bold" fill="#166534">18.000 km/h</text>\n  <text x="370" y="146" font-size="11" font-weight="bold" fill="#14532d">• Dünya:</text>\n  <text x="545" y="146" font-size="11" font-weight="bold" fill="#166534">40.320 km/h</text>\n  <text x="370" y="170" font-size="11" font-weight="bold" fill="#14532d">• Jüpiter (Mars\'ın ~12 katı):</text>\n  <text x="545" y="170" font-size="11" font-weight="bold" fill="#166534">216.720 km/h</text>\n  <text x="370" y="194" font-size="11" font-weight="bold" fill="#14532d">• Güneş (En büyük):</text>\n  <text x="545" y="194" font-size="11" font-weight="bold" fill="#166534">2.224.800 km/h</text>\n  <rect x="366" y="206" width="300" height="26" rx="5" fill="#dcfce7"/>\n  <text x="516" y="223" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">Gök cisminin M/R oranı büyüdükçe kurtulma hızı artar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YÖRÜNGEDEKİ UYDUNUN TOPLAM VE BAĞLANMA ENERJİSİ</text>\n\n  <!-- Sol Yörünge Şeması -->\n  <rect x="18" y="45" width="270" height="198" rx="10" fill="#0f172a" stroke="#334155" stroke-width="2"/>\n  <circle cx="153" cy="144" r="68" fill="none" stroke="#38bdf8" stroke-width="1.8" stroke-dasharray="6,4"/>\n  <circle cx="153" cy="144" r="28" fill="#2563eb" stroke="#93c5fd" stroke-width="2"/>\n  <text x="153" y="149" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">M</text>\n  <line x1="153" y1="144" x2="221" y2="144" stroke="#fbbf24" stroke-width="2"/>\n  <text x="187" y="137" text-anchor="middle" font-size="11" font-weight="bold" fill="#fbbf24">r</text>\n  <circle cx="221" cy="144" r="10" fill="#f59e0b" stroke="#fef08a" stroke-width="2"/>\n  <text x="242" y="148" font-size="11" font-weight="bold" fill="#fde047">m</text>\n  <text x="153" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#e2e8f0">r Yarıçaplı Çembersel Yörünge</text>\n  <text x="153" y="230" text-anchor="middle" font-size="10.5" fill="#93c5fd">Uzak yörüngede E(bağlanma) küçülür.</text>\n\n  <!-- Sağ Enerji Bağıntıları -->\n  <rect x="304" y="45" width="378" height="198" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="493" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">UYDUNUN ENERJİ DENKLEMLERİ</text>\n  <line x1="320" y1="76" x2="666" y2="76" stroke="#fcd34d" stroke-width="1.5"/>\n  <text x="322" y="98" font-size="11.5" fill="#78350f">• Potansiyel Enerji:</text>\n  <text x="490" y="98" font-size="11.5" font-weight="bold" fill="#92400e">Eₚ = -G · (M · m) / r</text>\n  <text x="322" y="122" font-size="11.5" fill="#78350f">• Kinetik Enerji:</text>\n  <text x="490" y="122" font-size="11.5" font-weight="bold" fill="#92400e">Eₖ = +1/2 · G · (M · m) / r</text>\n  <text x="322" y="146" font-size="11.5" fill="#78350f">• Toplam Mekanik Enerji:</text>\n  <text x="490" y="146" font-size="11.5" font-weight="bold" fill="#b91c1c">Eₜ = Eₚ + Eₖ = -1/2 · G · (M · m) / r</text>\n  <rect x="320" y="160" width="346" height="34" rx="6" fill="#fef3c7" stroke="#f59e0b"/>\n  <text x="493" y="182" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#78350f">E(bağlanma) = -Eₜ = +1/2 · G · (M · m) / r</text>\n  <text x="493" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Örnek: Eₜ(K) = -E ⇒ E_bağ(K) = +E | Eₜ(L) = -2E ⇒ E_bağ(L) = +2E</text>\n  <text x="493" y="232" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Oran: E_bağ(K) / E_bağ(L) = 1 / 2</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
